{
 "research_concepts": [
  "offensive lineup",
  "personnel effects",
  "shot mix",
  "shot selection",
  "lineup effects",
  "play-type mix"
 ],
 "methodological_questions": [
  "isolating lineup impact",
  "confounding in basketball analytics",
  "causal inference for lineup changes",
  "measuring shot distribution",
  "observational study design for personnel effects",
  "reliability of effect estimates"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-TMP-009",
   "status_as_recorded": "artifact",
   "finding": "An apparent PULL_UP-specific decline with exposure was found to be an artifact, consistent with a shooter-level confound. The effect shrunk from -0.0255 to -0.0063 without lineup fixed effects."
  },
  {
   "id": "FAM:SF-PAP-007",
   "status_as_recorded": "supported",
   "finding": "Teams run more cuts/PNR and fewer spot-ups/drives when a 'shaper' is on the floor (CUT +1.353pp, PNR +0.98pp, SPOT_UP -1.248pp, DRIVE -0.542pp)."
  },
  {
   "id": "FAM:SF34",
   "status_as_recorded": "inconclusive",
   "finding": "Offensive adaptation to an opponent's rim big being off the floor showed small shifts in play types (DRIVE +0.82pp, POST_UP +0.43pp, 3PA -1.79pp) and a very small, non-significant change in rim percentage (+0.12pp) and PPP (+0.008)."
  },
  {
   "id": "FAM:SF-PAP-009",
   "status_as_recorded": "supported",
   "finding": "Lineup coverage (>=1 organizer, shaper, terminal) varies within team, is separable from talent/counts, and talent control behaves."
  },
  {
   "id": "FAM:SF38",
   "status_as_recorded": "inconclusive",
   "finding": "League-wide within-game play type adaptation showed a small, non-significant slope (-0.0019 PPP/exposure), with only PULL_UP showing a significant decline (-0.030)."
  },
  {
   "id": "FAM:SF-APPM-021",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Descriptive analysis showed play-type mix shifts by halftime margin, crunch time, and after runs (e.g., crunch OTHER +6.08pp, PULL_UP +1.20pp)."
  },
  {
   "id": "FAM:SF-TMP-016",
   "status_as_recorded": "untestable",
   "finding": "Team heterogeneity in halftime play-type adaptation was untestable due to low measurement reliability, with a split-half correlation of -0.026."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Defensive scheme change within and across games was untestable due to label error in inferred labels, which could not separate real adjustments from offensive execution differences."
  },
  {
   "id": "FAM:SF-APPS-058",
   "status_as_recorded": "untestable",
   "finding": "Observed on-ball defensive scheme labels (DROP/ICE/SWITCH) were untestable due to very low confident label rates (14.9% and 3.3%) and unpopulated matchup fields."
  },
  {
   "id": "FAM:SF-PAP-008",
   "status_as_recorded": "inconclusive",
   "finding": "Shaper presence showed a non-focal play-type diversity (entropy) change near 0 (-0.0455), indicating rebalancing rather than expansion."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-TMP-009",
   "what_failed": "Attributing an apparent decline in PULL_UP effectiveness to defensive adaptation without controlling for lineup fixed effects.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); LIM:confounding; RISK:CONFOUNDING"
  },
  {
   "id": "FAM:SF34",
   "what_failed": "Detecting strong offensive adaptation to opponent's rim big being off floor.",
   "why": "LIM:small_sample; RISK:SAMPLE_SIZE_POWER (sub-1pp mix shifts with PPP t=+1.1; chat verdict WEAK/SMALL, will not carry a paper)"
  },
  {
   "id": "FAM:SF-TMP-016",
   "what_failed": "Measuring reliable team heterogeneity in halftime play-type adaptation.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:low_measurement_reliability; RISK:MEASURE_RELIABILITY (Team-season slope SD 0.6733 vs mean sampling SE 0.6508; split-half r -0.026)"
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes within and across games using available data.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; RISK:LABEL_ERROR (inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise)"
  },
  {
   "id": "FAM:SF-APPM-021",
   "what_failed": "Inferential tests on play-type mix shifts.",
   "why": "E_unclear (mechanism unclear from the records); LIM:label_or_classification_error; LIM:low_measurement_reliability; RISK:LABEL_ERROR; RISK:MEASURE_RELIABILITY (No inferential tests; OTHER label known to be noisy)"
  },
  {
   "id": "FAM:SF-APPS-058",
   "what_failed": "Labeling on-ball defensive schemes at usable rates using NBA matchup/PBP fields.",
   "why": "A_unanswerable (question not answerable with the data or design); LIM:label_or_classification_error; LIM:small_sample; RISK:LABEL_ERROR; RISK:SAMPLE_SIZE_POWER (Confident label rates 14.9% and 3.3%; NBA matchups feed did not populate switches_on)"
  }
 ],
 "evidence_establishes": [
  "Personnel changes (e.g., presence of specific player roles like a 'shaper') can lead to detectable shifts in a team's play-type mix, which implies changes in shot mix (FAM:SF-PAP-007).",
  "The concept of lineup coverage based on player roles is separable from talent and counts, suggesting that lineup composition attributes are meaningful (FAM:SF-PAP-009).",
  "Controlling for confounding factors, especially shooter-level effects and using fixed effects, is crucial when analyzing shot-related outcomes to avoid attributing artifacts to real effects (FAM:SF-TMP-009)."
 ],
 "evidence_does_not_establish": [
  "Whether *any* change in the offensive five reliably moves shot mix, beyond specific role players like 'shapers'.",
  "The typical magnitude and consistency of shot mix changes across a wide range of offensive lineup substitutions.",
  "The specific causal mechanisms through which different offensive personnel changes influence shot mix, beyond descriptive changes in play types.",
  "That effects of lineup changes on shot mix are consistently large enough to be easily detectable with standard observational designs; FAM:SF34 suggests such effects can be small and statistically inconclusive."
 ],
 "own_inferences": [
  "Since play-type mix directly influences shot mix (e.g., more PNR often means more shots at the rim or mid-range pull-ups), the evidence from SF-PAP-007 strongly suggests that personnel changes *can* affect shot mix.",
  "The data available (play-by-play, shot distance/result, lineups) is sufficient to define and measure 'shot mix' and 'offensive five' changes.",
  "The challenge lies in robustly isolating the causal effect of personnel changes from confounding factors and ensuring sufficient statistical power for potentially subtle effects."
 ],
 "uncertainties": [
  "The precise definition of 'shot mix' for this study (e.g., shot distance, shot type, assisted/unassisted, rim vs. three-point rate) is not specified, which could impact testability.",
  "The practical significance of the expected shifts in shot mix due to personnel changes is unknown; effects might be statistically significant but too small to be meaningful."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-PAP-007, confirmed that personnel changes can indeed lead to measurable shifts in play-type mix, which directly supports the premise that offensive lineup changes can move shot mix. This strengthened the decision to proceed, as it established a precedent for detecting such effects. However, FAM:SF-TMP-009 and FAM:SF34 highlighted significant methodological risks, especially confounding and small effect sizes leading to inconclusive results, which necessitates a robust design focusing on fixed effects and power considerations."
 },
 "testability": {
  "p_testable": 0.8,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-PAP-007",
   "FAM:SF34"
  ],
  "summary": "FAM:SF-PAP-007 directly supports that the presence of specific player roles ('shapers') on the floor shifts play-type mix (e.g., more cuts/PNR, fewer spot-ups/drives). This is strong evidence that personnel changes *can* influence play and, by extension, shot mix. FAM:SF34 explored offensive shot mix changes in response to *opponent* lineup changes, finding small and inconclusive effects on shot mix, highlighting the challenge of detecting such effects."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Changes in shot mix may be confounded by game state (score, time), opponent defensive adjustments, coaching strategy, or overall team talent rather than solely the specific offensive personnel change. Fixed effects for team-game-half or similar are critical."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Many specific offensive lineups may not accumulate enough possessions to reliably detect statistically significant changes in shot mix, especially if the effects are subtle, as suggested by FAM:SF34."
  },
  {
   "code": "EXPOSURE_SPARSITY",
   "text": "Some specific offensive lineup combinations will be rare, leading to insufficient data for robust analysis of their unique impact on shot mix."
  },
  {
   "code": "MEASURE_RELIABILITY",
   "text": "If 'shot mix' is broken down into very granular categories, the reliability of measuring shifts in these categories might be low, similar to issues seen with play-type adaptation measures in FAM:SF-TMP-016 and FAM:SF-APPM-021."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Offensive schemes and player roles can evolve within and across seasons, meaning a fixed definition of 'personnel effect' or 'shot mix' might not hold constant."
  }
 ],
 "predicted_outcome": {
  "supported": 0.5,
  "rejected": 0.2,
  "untestable": 0.1,
  "artifact": 0.1,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of changing the offensive five (specific player substitutions) on the distribution of shot types (e.g., rim attempts, mid-range, three-pointers) and shot distances, controlling for confounding factors.",
  "unit": "Possession-level shot attempt.",
  "sample": "All NBA regular season and playoff possessions from 2022-23, 2023-24, and 2024-25 seasons. Focus on possessions immediately following an offensive lineup change (substitution) by the team on offense.",
  "power": "Target a minimum of 80% power to detect a 1 percentage point (pp) shift in the proportion of rim attempts or three-point attempts, assuming a baseline rate of 30% for each. This will require a large number of lineup change events and subsequent possessions. Power calculations will inform the minimum number of possessions per lineup change needed.",
  "controls": "Use fixed effects for team-game-half to control for overall team strategy, opponent defense, and game state. Include player fixed effects for the players entering and exiting the game. Control for time remaining in the quarter/game, score differential, and opponent's defensive lineup composition. Consider using a within-lineup (or within-player-group) approach comparing possessions before and after a change, or a matched-sample design.",
  "falsification": "A falsification test could involve analyzing changes in shot mix for 'placebo' events, such as defensive substitutions where the offensive lineup remains unchanged, or analyzing changes for variables known not to be directly affected by personnel changes.",
  "multiplicity": "Adjust for multiple comparisons if testing changes across several shot mix categories (e.g., rim, mid-range, 3pt, specific play types) using methods like Holm-Bonferroni correction.",
  "decision_rule": "The hypothesis will be supported if at least two primary shot mix categories (e.g., rim attempt rate, 3-point attempt rate) show statistically significant (p < 0.05 after multiplicity adjustment) shifts in a consistent direction and magnitude deemed practically meaningful (e.g., >0.5pp shift) following offensive lineup changes, robust to different control specifications.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 regular season and playoffs data, processed into play-by-play and derived play-type possession records, including substitution rotation intervals, starters, defensive matchup minutes, and box-score summary."
 }
}

